function hstrip(track,slides,tx,q,railId,cntId,total){
 const W=stg.offsetWidth,maxT=Math.max(0,track.scrollWidth-W);
 tx+=((-q*maxT)-tx)*.10;
 track.style.transform='translate3d('+tx+'px,0,0)';
 const c0=W/2;
 slides.forEach(s=>{const c=s.offsetLeft+s.offsetWidth/2+tx;const d=(c-c0)/W;const ad=Math.min(1,Math.abs(d));
  s.style.transform=`perspective(1200px) translateY(${ad*26}px) rotateY(${d*-15}deg) scale(${1-ad*.15})`;
  s.style.opacity=String(1-Math.min(.62,ad*.85));
  s.style.zIndex=String(100-Math.round(ad*100));});
 g(railId).style.width=(q*100).toFixed(1)+'%';
 g(cntId).textContent='0'+Math.max(1,Math.min(total,Math.floor(q*total)+1))+' / 0'+total;
 return tx;}

